#if !defined(CONFIG_SCHED_TICKLESS) && \
    !defined(CONFIG_ALARM_ARCH) && !defined(CONFIG_TIMER_ARCH)
void clock_timer(void)
{
  irqstate_t flags;

  /* Increment the per-tick system counter */

  flags = write_seqlock_irqsave(&g_system_tick_lock);
