        g_report_snap.status = VG_UI_REPORT_READY;
        g_report_snap.err = 0;
        g_report_snap.from_agent = from_agent;
        g_report_snap.truncated =
          (strlen(body) + 1 >= sizeof(g_report_snap.body));
        g_report_snap.version++;
