static int write_all(int fd, const unsigned char *data, size_t len)
{
  while (len > 0)
    {
      ssize_t n = write(fd, data, len);
      if (n < 0 && errno == EINTR) continue;
      if (n <= 0) return n < 0 ? -errno : -EIO;
      data += n;
      len -= (size_t)n;
    }
  return 0;
}

